-- GENERATED by scripts/bundle-migrations.sh — do not edit by hand.
-- Source of truth is supabase/migrations/*.sql. Safe to re-run: every
-- statement is idempotent.


-- ======================== 00_prelude.sql ========================

-- ===========================================================================
-- 00_prelude.sql — extensions, enums, and locking the anon role down.
--
-- Every migration here is written to be safely re-runnable: paste the whole
-- bundle again and it should succeed, not error on "already exists".
-- ===========================================================================

create extension if not exists "pgcrypto" with schema extensions;

-- The publishable key is baked into a public GitHub Pages bundle, so treat
-- `anon` as hostile. It keeps USAGE on the schema — PostgREST needs that to
-- resolve ping() below — but gets no tables and no functions beyond the ones
-- granted by name.
grant usage on schema public to anon, authenticated;

revoke all on all tables in schema public from anon;
alter default privileges in schema public revoke all on tables    from anon;
alter default privileges in schema public revoke all on sequences from anon;

-- Functions are EXECUTE-able by PUBLIC by default, which would quietly include
-- anon. Default-deny instead; every callable function is granted explicitly.
alter default privileges in schema public revoke all on functions from public, anon;

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
do $$
begin
  create type public.member_role as enum ('member', 'organizer');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type public.trip_status as enum ('planning', 'upcoming', 'active', 'archived');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type public.rsvp_status as enum ('yes', 'no', 'maybe', 'pending');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type public.meal_type as enum ('breakfast', 'lunch', 'dinner', 'snack');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type public.event_kind as enum ('activity', 'travel', 'birthday', 'reminder', 'chore', 'other');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type public.expense_category as enum ('house', 'golf_cart', 'groceries', 'dining', 'activities', 'travel', 'supplies', 'fuel', 'other');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type public.split_method as enum ('equal', 'custom', 'household');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type public.photo_kind as enum ('trip', 'house', 'journal');
exception when duplicate_object then null;
end $$;

-- ---------------------------------------------------------------------------
-- Keep-alive. Free Supabase projects pause after 7 days of no activity, and
-- this app is idle ~51 weeks a year. A weekly GitHub Action calls ping() to
-- reset that timer. It writes a row, so it counts as genuine activity.
-- ---------------------------------------------------------------------------
create table if not exists public.heartbeat (
  id        boolean primary key default true check (id),
  last_ping timestamptz not null default now()
);

insert into public.heartbeat (id) values (true) on conflict (id) do nothing;

alter table public.heartbeat enable row level security;
-- Deliberately no policies: nobody reaches this through the REST API. ping()
-- is the only door, and it is SECURITY DEFINER so policies don't apply to it.

create or replace function public.ping()
returns timestamptz
language sql
security definer
set search_path = ''
as $$
  update public.heartbeat set last_ping = now() where id returning last_ping;
$$;

-- Callable without a session: the cron job has no user to sign in as. The
-- worst it can do is bump one timestamp.
grant execute on function public.ping() to anon, authenticated;

-- ======================== 01_identity.sql ========================

-- ===========================================================================
-- 01_identity.sql — households, the invite allowlist, and profiles.
--
-- Ordering matters: households <- profiles <- allowed_emails, so every foreign
-- key can be declared inline.
--
-- WHY THERE IS NO TRIGGER ON auth.users
--
-- The usual Supabase pattern hangs an AFTER INSERT trigger on auth.users to
-- mirror each new account into `profiles`. That is no longer possible: the
-- `postgres` role does not own auth.users, so CREATE TRIGGER on it fails with
--   ERROR 42501: must be owner of relation users
-- and because the SQL editor runs a script in one transaction, that single
-- failure silently rolls back every table in the file.
--
-- Instead the client calls ensure_profile() right after sign-in. Supabase now
-- recommends this direction anyway, and it has a real advantage: it re-syncs
-- is_active on every call, so adding someone to the allowlist and having them
-- press "Check again" is enough to let them in.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- Households. The unit that cooks a dinner and takes a share of the house cost.
-- ---------------------------------------------------------------------------
create table if not exists public.households (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (length(btrim(name)) between 1 and 80),
  color      text not null default '#1f8f89' check (color ~* '^#[0-9a-f]{6}$'),
  sort_order smallint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Profiles. `is_active` is the gate every RLS policy checks. It is derived
-- from allowed_emails and must never be writable by the person it describes.
-- ---------------------------------------------------------------------------
create table if not exists public.profiles (
  id           uuid primary key references auth.users(id) on delete cascade,
  email        text not null unique check (email = lower(email)),
  full_name    text not null default '',
  display_name text generated always as
                 (coalesce(nullif(btrim(full_name), ''), split_part(email, '@', 1))) stored,
  avatar_path  text,
  household_id uuid references public.households(id) on delete set null,
  role         public.member_role not null default 'member',
  is_active    boolean not null default false,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index if not exists profiles_household_idx on public.profiles (household_id);
create index if not exists profiles_active_idx    on public.profiles (is_active) where is_active;

-- Column-level grants, and why they are not optional:
-- RLS filters *rows*, not *columns*. A policy saying "you may update your own
-- profile" would otherwise let anyone set role='organizer' or is_active=true
-- on themselves. These grants are the only thing preventing that.
revoke all on public.profiles from authenticated;
grant select on public.profiles to authenticated;
grant update (full_name, avatar_path, household_id) on public.profiles to authenticated;
-- No INSERT: only ensure_profile() creates rows, and it runs as the owner.
-- No DELETE: removal cascades from auth.users.

-- ---------------------------------------------------------------------------
-- The invite allowlist. Source of truth for "is this person family?".
-- ---------------------------------------------------------------------------
create table if not exists public.allowed_emails (
  email      text primary key
               check (email = lower(email) and position('@' in email) > 1),
  note       text,
  invited_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

grant select, insert, update, delete on public.allowed_emails to authenticated;
grant select, insert, update on public.households to authenticated;
grant delete on public.households to authenticated;

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists households_touch on public.households;
create trigger households_touch before update on public.households
  for each row execute function public.touch_updated_at();

drop trigger if exists profiles_touch on public.profiles;
create trigger profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- ensure_profile() — called by the app immediately after sign-in.
--
-- SECURITY DEFINER so it can write columns the caller is not granted, and so
-- it bypasses the profiles policies while creating the very row those policies
-- depend on.
-- ---------------------------------------------------------------------------
create or replace function public.ensure_profile()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id     uuid := (select auth.uid());
  v_email  text := lower(nullif((select auth.jwt() ->> 'email'), ''));
  v_active boolean;
begin
  if v_id is null or v_email is null then
    raise exception 'Not signed in' using errcode = '42501';
  end if;

  v_active := exists (select 1 from public.allowed_emails a where a.email = v_email);

  insert into public.profiles (id, email, is_active)
  values (v_id, v_email, v_active)
  on conflict (id) do update
     set email     = excluded.email,
         is_active = excluded.is_active;
end;
$$;

revoke execute on function public.ensure_profile() from public, anon;
grant   execute on function public.ensure_profile() to authenticated;

-- ---------------------------------------------------------------------------
-- Allowlist changes take effect immediately, in both directions.
--
-- This trigger is on our own table, so it is allowed — unlike one on
-- auth.users. Deriving is_active here (rather than reading the allowlist in
-- every policy) means revoking someone applies on their very next query, with
-- no waiting for a token to expire.
-- ---------------------------------------------------------------------------
create or replace function public.sync_allowed_email()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    update public.profiles set is_active = false where email = old.email;
    return old;
  end if;

  update public.profiles set is_active = true where email = new.email;
  return new;
end;
$$;

drop trigger if exists allowed_emails_sync on public.allowed_emails;
create trigger allowed_emails_sync
  after insert or delete on public.allowed_emails
  for each row execute function public.sync_allowed_email();

-- ======================== 02_helpers.sql ========================

-- ===========================================================================
-- 02_helpers.sql — the membership checks every RLS policy calls.
--
-- THE RECURSION TRAP THIS EXISTS TO AVOID
--
-- The obvious policy is also a broken one:
--
--   create policy p on public.profiles for select to authenticated
--   using (exists (select 1 from public.profiles
--                  where id = auth.uid() and is_active));
--
-- That inner SELECT on `profiles` re-enters this very policy, forever:
--   ERROR 42P17: infinite recursion detected in policy for relation "profiles"
--
-- A SECURITY DEFINER function runs as its owner (postgres), who owns the table,
-- and table owners are exempt from RLS unless FORCE ROW LEVEL SECURITY is set.
-- So the lookup inside these functions evaluates no policy at all.
--
-- Two rules, both load-bearing:
--
--   1. `set search_path = ''` with fully-qualified names. Without it, someone
--      who can create objects could shadow `public.profiles` and hijack the
--      definer context. Supabase's linter flags this as
--      `function_search_path_mutable`.
--
--   2. Call these as `(select public.is_member())` in policies, never bare.
--      Wrapping in a subquery makes the planner evaluate it once per query
--      instead of once per row.
-- ===========================================================================

create or replace function public.is_member()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.profiles p
     where p.id = (select auth.uid())
       and p.is_active
  );
$$;

create or replace function public.is_organizer()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.profiles p
     where p.id = (select auth.uid())
       and p.is_active
       and p.role = 'organizer'
  );
$$;

create or replace function public.my_household_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select p.household_id from public.profiles p where p.id = (select auth.uid());
$$;

revoke execute on function public.is_member(), public.is_organizer(), public.my_household_id()
  from public, anon;
grant execute on function public.is_member(), public.is_organizer(), public.my_household_id()
  to authenticated;

-- ======================== 03_gate.sql ========================

-- ===========================================================================
-- 03_gate.sql — refuse signup for anyone not on the invite list.
--
-- This is the second of two layers. RLS (`is_active`) is what actually protects
-- the data; this hook simply stops junk auth.users rows from being created at
-- all, which keeps the account list clean and avoids burning the email quota on
-- strangers.
--
-- MANUAL STEP: register this in the Supabase dashboard under
--   Authentication -> Hooks -> Before User Created
-- The SQL alone does nothing until that hook is pointed at it.
-- ===========================================================================

create or replace function public.hook_restrict_signup(event jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_email text := lower(event -> 'user' ->> 'email');
begin
  if exists (select 1 from public.allowed_emails a where a.email = v_email) then
    return '{}'::jsonb;  -- empty object == allow
  end if;

  return jsonb_build_object(
    'error', jsonb_build_object(
      'http_code', 403,
      'message',   'This site is invite-only. Ask Luke to add your email address.'
    )
  );
end;
$$;

grant  execute on function public.hook_restrict_signup(jsonb) to supabase_auth_admin;
revoke execute on function public.hook_restrict_signup(jsonb) from authenticated, anon, public;

-- ======================== 04_identity_rls.sql ========================

-- ===========================================================================
-- 04_identity_rls.sql — policies for households, profiles, allowed_emails.
-- ===========================================================================

alter table public.households    enable row level security;
alter table public.profiles      enable row level security;
alter table public.allowed_emails enable row level security;

-- Note on FORCE ROW LEVEL SECURITY: do NOT set it on `profiles`. Forcing RLS
-- applies policies to the table owner too, which would put is_member() straight
-- back into the recursion it was written to escape.

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles
  for select to authenticated
  using ( (select public.is_member()) or id = (select auth.uid()) );
  -- The OR lets a signed-in but not-yet-approved person load their own row, so
  -- they see "your account is pending" instead of an empty screen.

drop policy if exists profiles_update_self on public.profiles;
create policy profiles_update_self on public.profiles
  for update to authenticated
  using      ( id = (select auth.uid()) )
  with check ( id = (select auth.uid()) );
  -- Escalation to organizer is blocked by the column-level GRANT in
  -- 01_identity.sql, not here. Both layers are required.

-- ---------------------------------------------------------------------------
-- households — any member may create and rename; only organizers delete.
-- ---------------------------------------------------------------------------
drop policy if exists households_select on public.households;
create policy households_select on public.households
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists households_insert on public.households;
create policy households_insert on public.households
  for insert to authenticated with check ( (select public.is_member()) );

drop policy if exists households_update on public.households;
create policy households_update on public.households
  for update to authenticated
  using      ( (select public.is_member()) )
  with check ( (select public.is_member()) );

drop policy if exists households_delete on public.households;
create policy households_delete on public.households
  for delete to authenticated using ( (select public.is_organizer()) );

-- ---------------------------------------------------------------------------
-- allowed_emails — organizers only. This list is who can enter the app at all.
-- ---------------------------------------------------------------------------
drop policy if exists allowed_emails_all on public.allowed_emails;
create policy allowed_emails_all on public.allowed_emails
  for all to authenticated
  using      ( (select public.is_organizer()) )
  with check ( (select public.is_organizer()) );

-- ======================== 06_trips.sql ========================

-- ===========================================================================
-- 06_trips.sql — one trip per year, the house, and the codes everyone texts
-- about on arrival day.
-- ===========================================================================

create table if not exists public.trips (
  id         uuid primary key default gen_random_uuid(),
  year       integer not null unique check (year between 2000 and 2100),
  name       text not null default '',
  start_date date,
  end_date   date,
  status     public.trip_status not null default 'planning',
  notes      text,
  created_by uuid not null references public.profiles(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint trips_dates_ordered
    check (end_date is null or start_date is null or end_date >= start_date)
);

create index if not exists trips_year_desc_idx on public.trips (year desc);

create table if not exists public.houses (
  id              uuid primary key default gen_random_uuid(),
  trip_id         uuid not null references public.trips(id) on delete cascade,
  name            text not null default '',
  address_line1   text,
  address_line2   text,
  city            text not null default 'Port Aransas',
  state           text not null default 'TX',
  postal_code     text,
  -- Plotted on the all-years map. Both or neither; a lone latitude is a bug.
  lat             numeric(9, 6) check (lat between -90 and 90),
  lng             numeric(9, 6) check (lng between -180 and 180),
  rental_url      text check (rental_url is null or rental_url ~* '^https?://'),
  rental_platform text,
  cost_cents      integer check (cost_cents is null or cost_cents >= 0),
  bedrooms        smallint check (bedrooms is null or bedrooms between 0 and 30),
  sleeps          smallint check (sleeps is null or sleeps between 0 and 60),
  notes           text,
  created_by      uuid not null references public.profiles(id) on delete restrict,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint houses_latlng_together check ((lat is null) = (lng is null))
);

create index if not exists houses_trip_idx   on public.houses (trip_id);
create index if not exists houses_latlng_idx on public.houses (lat, lng) where lat is not null;

-- Gate code, pool code, wifi, trash day. Free-form label/value so a new house
-- with a quirk ("outdoor shower key") needs no migration.
create table if not exists public.house_info (
  id         uuid primary key default gen_random_uuid(),
  house_id   uuid not null references public.houses(id) on delete cascade,
  label      text not null check (length(btrim(label)) between 1 and 60),
  value      text not null default '',
  sort_order smallint not null default 0,
  updated_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (house_id, label)
);

create index if not exists house_info_house_idx on public.house_info (house_id, sort_order);

drop trigger if exists trips_touch on public.trips;
create trigger trips_touch before update on public.trips
  for each row execute function public.touch_updated_at();
drop trigger if exists houses_touch on public.houses;
create trigger houses_touch before update on public.houses
  for each row execute function public.touch_updated_at();
drop trigger if exists house_info_touch on public.house_info;
create trigger house_info_touch before update on public.house_info
  for each row execute function public.touch_updated_at();

-- Table-level grants. 00_prelude changes the schema's default privileges, so
-- state these explicitly rather than relying on what a new table inherits.
grant select, insert, update, delete on public.trips      to authenticated;
grant select, insert, update, delete on public.houses     to authenticated;
grant select, insert, update, delete on public.house_info to authenticated;

-- ======================== 07_trips_rls.sql ========================

-- ===========================================================================
-- 07_trips_rls.sql
--
-- Trips and houses are organizer-managed: they're settled once a year by
-- whoever books, and an accidental edit is annoying to reconstruct.
-- house_info is deliberately open to every member — the whole point is that
-- anyone can correct the wifi password the moment they find it wrong.
-- ===========================================================================

alter table public.trips      enable row level security;
alter table public.houses     enable row level security;
alter table public.house_info enable row level security;

drop policy if exists trips_select on public.trips;
create policy trips_select on public.trips
  for select to authenticated using ( (select public.is_member()) );
drop policy if exists trips_write on public.trips;
create policy trips_write on public.trips
  for all to authenticated
  using      ( (select public.is_organizer()) )
  with check ( (select public.is_organizer()) );

drop policy if exists houses_select on public.houses;
create policy houses_select on public.houses
  for select to authenticated using ( (select public.is_member()) );
drop policy if exists houses_write on public.houses;
create policy houses_write on public.houses
  for all to authenticated
  using      ( (select public.is_organizer()) )
  with check ( (select public.is_organizer()) );

drop policy if exists house_info_select on public.house_info;
create policy house_info_select on public.house_info
  for select to authenticated using ( (select public.is_member()) );
drop policy if exists house_info_write on public.house_info;
create policy house_info_write on public.house_info
  for all to authenticated
  using      ( (select public.is_member()) )
  with check ( (select public.is_member()) );

-- ======================== 09_allowlist_role.sql ========================

-- ===========================================================================
-- 09_allowlist_role.sql — let the invite list decide who is an organizer.
--
-- Without this, ensure_profile() creates every account as 'member', so a new
-- organizer needs a manual SQL UPDATE after their first sign-in -- exactly the
-- friction the invite code removed from signup. Worse, the very first person
-- in is a member, and members cannot create trips, so a fresh project has
-- nobody who can set one up.
-- ===========================================================================

alter table public.allowed_emails
  add column if not exists role public.member_role not null default 'member';

create or replace function public.ensure_profile()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id     uuid := (select auth.uid());
  v_email  text := lower(nullif((select auth.jwt() ->> 'email'), ''));
  v_active boolean;
  v_role   public.member_role;
begin
  if v_id is null or v_email is null then
    raise exception 'Not signed in' using errcode = '42501';
  end if;

  select true, a.role
    into v_active, v_role
    from public.allowed_emails a
   where a.email = v_email;

  v_active := coalesce(v_active, false);
  v_role   := coalesce(v_role, 'member');

  insert into public.profiles (id, email, is_active, role)
  values (v_id, v_email, v_active, v_role)
  on conflict (id) do update
     set email     = excluded.email,
         is_active = excluded.is_active;
     -- role is intentionally NOT updated here: promoting or demoting someone
     -- is a deliberate act, and re-deriving it on every sign-in would undo it.
end;
$$;

revoke execute on function public.ensure_profile() from public, anon;
grant   execute on function public.ensure_profile() to authenticated;

-- ======================== 10_remove_invite_codes.sql ========================

-- ===========================================================================
-- 10_remove_invite_codes.sql — back to invite-by-email only.
--
-- Self-serve signup with a shared code is removed. The email allowlist is the
-- sole way in: an address is either on it or it is not. Fewer moving parts,
-- and no shared secret to leak, screenshot or rotate.
-- ===========================================================================

drop table if exists public.invite_codes;

create or replace function public.hook_restrict_signup(event jsonb)
returns jsonb
language plpgsql
stable                      -- allowlist-only: this no longer writes anything
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(coalesce(event -> 'user' ->> 'email', '')));
begin
  if v_email = '' then
    return jsonb_build_object('error', jsonb_build_object(
      'http_code', 400,
      'message',   'We need an email address to sign you in.'));
  end if;

  if exists (select 1 from public.allowed_emails a where a.email = v_email) then
    return '{}'::jsonb;
  end if;

  return jsonb_build_object('error', jsonb_build_object(
    'http_code', 403,
    'message',   'This site is invite-only. Ask Luke to add your email address.'));
end;
$$;

grant  execute on function public.hook_restrict_signup(jsonb) to supabase_auth_admin;
revoke execute on function public.hook_restrict_signup(jsonb) from authenticated, anon, public;

-- ======================== 11_admin.sql ========================

-- ===========================================================================
-- 11_admin.sql — what the organizer's member screen needs.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- One row per invited address, with whatever we know about the person.
--
-- security_invoker = true is NOT optional. A view runs as its OWNER by default,
-- and the owner (postgres) bypasses RLS entirely — a plain `create view` over
-- allowed_emails would expose the whole invite list to every signed-in member.
-- With invoker set, the caller's policies apply, so only organizers see rows.
-- ---------------------------------------------------------------------------
create or replace view public.admin_members
with (security_invoker = true) as
select
  a.email,
  a.note,
  a.role                       as invited_role,
  a.created_at                 as invited_at,
  p.id                         as profile_id,
  p.display_name,
  p.role                       as profile_role,
  coalesce(p.is_active, false) as is_active,
  h.name                       as household_name,
  (p.id is not null)           as has_signed_in
from public.allowed_emails a
left join public.profiles   p on p.email = a.email
left join public.households h on h.id = p.household_id;

revoke all on public.admin_members from public, anon;
grant select on public.admin_members to authenticated;

-- ---------------------------------------------------------------------------
-- Never let the project end up with nobody who can create a trip.
--
-- A trigger rather than a check inside the RPC, so it holds no matter which
-- path the delete came from — including a hand-written REST call.
-- ---------------------------------------------------------------------------
create or replace function public.protect_last_organizer()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if old.role = 'organizer'
     and (select count(*) from public.allowed_emails where role = 'organizer') <= 1 then
    raise exception 'That is the only organizer. Make someone else an organizer first.'
      using errcode = 'check_violation';
  end if;
  return old;
end;
$$;

drop trigger if exists allowed_emails_protect_last_organizer on public.allowed_emails;
create trigger allowed_emails_protect_last_organizer
  before delete on public.allowed_emails
  for each row execute function public.protect_last_organizer();

-- ---------------------------------------------------------------------------
-- Changing someone else's role needs a function: the column-level grants in
-- 01_identity.sql deliberately withhold `role` from authenticated, and the
-- profiles policy only allows self-updates. Both of those are what stop a
-- member promoting themselves, so neither should be relaxed.
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_role(
  target_email text,
  new_role     public.member_role
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(target_email));
begin
  if not (select public.is_organizer()) then
    raise exception 'Organizers only.' using errcode = '42501';
  end if;

  if new_role <> 'organizer'
     and (select count(*) from public.allowed_emails where role = 'organizer') <= 1
     and exists (select 1 from public.allowed_emails
                  where email = v_email and role = 'organizer') then
    raise exception 'That is the only organizer. Make someone else an organizer first.'
      using errcode = 'check_violation';
  end if;

  update public.allowed_emails set role = new_role where email = v_email;
  update public.profiles        set role = new_role where email = v_email;

  if not found and not exists (select 1 from public.allowed_emails where email = v_email) then
    raise exception 'No such member.' using errcode = 'no_data_found';
  end if;
end;
$$;

revoke execute on function public.admin_set_role(text, public.member_role) from public, anon;
grant   execute on function public.admin_set_role(text, public.member_role) to authenticated;

-- ---------------------------------------------------------------------------
-- Bulk invite. Takes whatever was pasted in, normalises it, and reports what
-- happened so the screen can say "4 added, 2 already there, 1 not an address".
-- ---------------------------------------------------------------------------
create or replace function public.admin_add_members(
  emails      text[],
  as_organizer boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_raw      text;
  v_email    text;
  v_added    text[] := '{}';
  v_existing text[] := '{}';
  v_invalid  text[] := '{}';
  v_role     public.member_role := case when as_organizer then 'organizer' else 'member' end;
begin
  if not (select public.is_organizer()) then
    raise exception 'Organizers only.' using errcode = '42501';
  end if;

  foreach v_raw in array coalesce(emails, '{}') loop
    v_email := lower(btrim(v_raw));
    continue when v_email = '';

    if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[a-z]{2,}$' then
      v_invalid := v_invalid || v_email;
      continue;
    end if;

    if exists (select 1 from public.allowed_emails a where a.email = v_email) then
      v_existing := v_existing || v_email;
      continue;
    end if;

    insert into public.allowed_emails (email, role, invited_by)
    values (v_email, v_role, (select auth.uid()));
    v_added := v_added || v_email;
  end loop;

  return jsonb_build_object(
    'added',    to_jsonb(v_added),
    'existing', to_jsonb(v_existing),
    'invalid',  to_jsonb(v_invalid));
end;
$$;

revoke execute on function public.admin_add_members(text[], boolean) from public, anon;
grant   execute on function public.admin_add_members(text[], boolean) to authenticated;

-- ======================== 12_invite_codes.sql ========================

-- ===========================================================================
-- 12_invite_codes.sql — self-serve signup with a shared family code.
--
-- Restores what 08 added and 10 removed, with one change: codes are managed
-- from the Members screen rather than seeded by hand in SQL.
--
-- A redeemed code writes the new address into allowed_emails, so this adds
-- convenience without giving up per-person control — revoking someone stays a
-- one-row delete, and there is a record of who joined with which code.
-- ===========================================================================

create table if not exists public.invite_codes (
  code       text primary key
               check (code = lower(code) and length(code) between 4 and 64),
  label      text,
  active     boolean not null default true,
  expires_at timestamptz,
  max_uses   integer check (max_uses is null or max_uses > 0),
  uses       integer not null default 0,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

grant select, insert, update, delete on public.invite_codes to authenticated;
alter table public.invite_codes enable row level security;

-- Organizers only. A member has no reason to read the codes out of the API,
-- and anon must never reach them.
drop policy if exists invite_codes_all on public.invite_codes;
create policy invite_codes_all on public.invite_codes
  for all to authenticated
  using      ( (select public.is_organizer()) )
  with check ( (select public.is_organizer()) );

-- ---------------------------------------------------------------------------
-- The signup gate.
--
-- VOLATILE, not STABLE: it writes — it bumps the use counter and records the
-- new member. Marking it stable makes those writes fail.
--
-- The payload exposes the client's metadata as `user_metadata`. The column it
-- eventually lands in is raw_user_meta_data, which is the wrong name to read
-- here; this was verified against a real Before User Created payload.
-- ---------------------------------------------------------------------------
create or replace function public.hook_restrict_signup(event jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(coalesce(event -> 'user' ->> 'email', '')));
  v_code  text := lower(btrim(coalesce(
                    event -> 'user' -> 'user_metadata' ->> 'invite_code', '')));
begin
  if v_email = '' then
    return jsonb_build_object('error', jsonb_build_object(
      'http_code', 400, 'message', 'We need an email address to sign you in.'));
  end if;

  -- Already invited by address, or joined with a code previously.
  if exists (select 1 from public.allowed_emails a where a.email = v_email) then
    return '{}'::jsonb;
  end if;

  if v_code = '' then
    -- The sign-in screen watches for this marker to reveal the code field, so
    -- returning members never have to see it.
    return jsonb_build_object('error', jsonb_build_object(
      'http_code', 403,
      'message', 'NEEDS_CODE: Enter the family code to join. Ask Luke if you do not have it.'));
  end if;

  -- One statement covers validity, expiry, the use cap and the increment, so
  -- two people redeeming the last use at once cannot both succeed.
  update public.invite_codes
     set uses = uses + 1
   where code = v_code
     and active
     and (expires_at is null or expires_at > now())
     and (max_uses is null or uses < max_uses);

  if not found then
    return jsonb_build_object('error', jsonb_build_object(
      'http_code', 403, 'message', 'That family code is not right. Check with Luke.'));
  end if;

  insert into public.allowed_emails (email, note)
  values (v_email, 'joined with code: ' || v_code)
  on conflict (email) do nothing;

  return '{}'::jsonb;
end;
$$;

grant  execute on function public.hook_restrict_signup(jsonb) to supabase_auth_admin;
revoke execute on function public.hook_restrict_signup(jsonb) from authenticated, anon, public;

-- ======================== 13_rsvps.sql ========================

-- ===========================================================================
-- 13_rsvps.sql — who is coming each year, and gating the house codes on it.
-- ===========================================================================

create table if not exists public.rsvps (
  id             uuid primary key default gen_random_uuid(),
  trip_id        uuid not null references public.trips(id) on delete cascade,
  profile_id     uuid references public.profiles(id) on delete cascade,
  -- Family without an account (Grandma) still needs to show up in the roster
  -- and the headcount, so a row can name a guest instead of a profile.
  guest_name     text,
  status         public.rsvp_status not null default 'pending',
  adults         smallint not null default 0 check (adults between 0 and 40),
  kids           smallint not null default 0 check (kids between 0 and 40),
  headcount      smallint generated always as (adults + kids) stored,
  arrival_date   date,
  departure_date date,
  notes          text,
  created_by     uuid not null references public.profiles(id) on delete restrict,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint rsvp_identity
    check (num_nonnulls(profile_id, nullif(btrim(coalesce(guest_name, '')), '')) = 1),
  constraint rsvp_dates_ordered
    check (departure_date is null or arrival_date is null or departure_date >= arrival_date)
);

create unique index if not exists rsvps_one_per_member
  on public.rsvps (trip_id, profile_id) where profile_id is not null;
create index if not exists rsvps_trip_idx on public.rsvps (trip_id);

grant select, insert, update, delete on public.rsvps to authenticated;

drop trigger if exists rsvps_touch on public.rsvps;
create trigger rsvps_touch before update on public.rsvps
  for each row execute function public.touch_updated_at();

alter table public.rsvps enable row level security;

drop policy if exists rsvps_select on public.rsvps;
create policy rsvps_select on public.rsvps
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists rsvps_insert on public.rsvps;
create policy rsvps_insert on public.rsvps
  for insert to authenticated
  with check (
    (select public.is_member())
    and created_by = (select auth.uid())
    and ( profile_id = (select auth.uid())     -- yourself
          or profile_id is null                -- a guest you are bringing
          or (select public.is_organizer()) )  -- organizer filling in for someone
  );

drop policy if exists rsvps_update on public.rsvps;
create policy rsvps_update on public.rsvps
  for update to authenticated
  using      ( profile_id = (select auth.uid()) or created_by = (select auth.uid())
               or (select public.is_organizer()) )
  with check ( profile_id = (select auth.uid()) or created_by = (select auth.uid())
               or (select public.is_organizer()) );

drop policy if exists rsvps_delete on public.rsvps;
create policy rsvps_delete on public.rsvps
  for delete to authenticated
  using ( profile_id = (select auth.uid()) or created_by = (select auth.uid())
          or (select public.is_organizer()) );

-- ---------------------------------------------------------------------------
-- House codes now require an RSVP.
--
-- Signup is self-serve behind a shared code, so "any signed-in member" is a
-- looser door than it was when the allowlist was the only way in. Requiring a
-- yes for the year costs real attendees nothing — they RSVP anyway — and means
-- a stray account cannot read the gate code.
-- ---------------------------------------------------------------------------
create or replace function public.is_attending(p_trip_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.rsvps r
     where r.trip_id = p_trip_id
       and r.profile_id = (select auth.uid())
       and r.status = 'yes'
  );
$$;

revoke execute on function public.is_attending(uuid) from public, anon;
grant   execute on function public.is_attending(uuid) to authenticated;

drop policy if exists house_info_select on public.house_info;
drop policy if exists house_info_write  on public.house_info;

create policy house_info_select on public.house_info
  for select to authenticated
  using (
    (select public.is_member())
    and (
      (select public.is_organizer())
      or exists (
        select 1 from public.houses h
         where h.id = house_info.house_id
           and public.is_attending(h.trip_id)
      )
    )
  );

-- Same audience for writes: if you cannot see a code you have no business
-- editing it. Still collaborative among everyone who is actually going.
create policy house_info_write on public.house_info
  for all to authenticated
  using (
    (select public.is_member())
    and (
      (select public.is_organizer())
      or exists (select 1 from public.houses h
                  where h.id = house_info.house_id
                    and public.is_attending(h.trip_id))
    )
  )
  with check (
    (select public.is_member())
    and (
      (select public.is_organizer())
      or exists (select 1 from public.houses h
                  where h.id = house_info.house_id
                    and public.is_attending(h.trip_id))
    )
  );

-- ======================== 14_house_reviews.sql ========================

-- ===========================================================================
-- 14_house_reviews.sql — rate and comment on the house.
--
-- The point is next year's booking: "was this one worth repeating?" is
-- impossible to answer from memory a year later, and currently lives in a
-- group text nobody can find.
-- ===========================================================================

create table if not exists public.house_reviews (
  id         uuid primary key default gen_random_uuid(),
  house_id   uuid not null references public.houses(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  rating     smallint check (rating between 1 and 5),
  comment    text check (length(comment) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- One review each, edited in place, rather than a thread of restatements.
  unique (house_id, profile_id),
  -- A row with neither a rating nor a comment says nothing.
  constraint review_has_content
    check (rating is not null or nullif(btrim(coalesce(comment, '')), '') is not null)
);

create index if not exists house_reviews_house_idx on public.house_reviews (house_id);

grant select, insert, update, delete on public.house_reviews to authenticated;

drop trigger if exists house_reviews_touch on public.house_reviews;
create trigger house_reviews_touch before update on public.house_reviews
  for each row execute function public.touch_updated_at();

alter table public.house_reviews enable row level security;

-- Everyone reads every review: the whole value is seeing them side by side.
drop policy if exists house_reviews_select on public.house_reviews;
create policy house_reviews_select on public.house_reviews
  for select to authenticated using ( (select public.is_member()) );

-- Author-owned, like the journal. Nobody rewrites your opinion — and the
-- with-check on update stops handing authorship to someone else.
drop policy if exists house_reviews_insert on public.house_reviews;
create policy house_reviews_insert on public.house_reviews
  for insert to authenticated
  with check ( (select public.is_member()) and profile_id = (select auth.uid()) );

drop policy if exists house_reviews_update on public.house_reviews;
create policy house_reviews_update on public.house_reviews
  for update to authenticated
  using      ( profile_id = (select auth.uid()) )
  with check ( profile_id = (select auth.uid()) );

drop policy if exists house_reviews_delete on public.house_reviews;
create policy house_reviews_delete on public.house_reviews
  for delete to authenticated
  using ( profile_id = (select auth.uid()) or (select public.is_organizer()) );

-- ======================== 15_photos.sql ========================

-- ===========================================================================
-- 15_photos.sql — image storage, starting with the house photo.
--
-- The bucket is PRIVATE and read through signed URLs. A public bucket would be
-- a permanent unauthenticated link to the family's photos, guessable or not.
-- ===========================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'photos', 'photos', false, 26214400,
  array['image/jpeg','image/png','image/webp','image/avif','image/heic','image/heif']
)
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

create table if not exists public.photos (
  id           uuid primary key default gen_random_uuid(),
  trip_id      uuid references public.trips(id) on delete cascade,
  house_id     uuid references public.houses(id) on delete cascade,
  kind         public.photo_kind not null default 'trip',
  storage_path text not null unique,
  caption      text,
  -- Stored at upload so the grid can reserve space and not jump as images
  -- load; there is no server to probe dimensions later.
  width        integer,
  height       integer,
  bytes        integer,
  sort_order   smallint not null default 0,
  uploaded_by  uuid not null references public.profiles(id) on delete restrict,
  created_at   timestamptz not null default now(),
  constraint photos_has_owner check (trip_id is not null or house_id is not null)
);

create index if not exists photos_house_idx on public.photos (house_id, sort_order)
  where house_id is not null;
create index if not exists photos_trip_idx on public.photos (trip_id, sort_order, created_at desc);

grant select, insert, update, delete on public.photos to authenticated;
alter table public.photos enable row level security;

-- House photos are just a picture of the house, so every member sees them.
-- Deliberately NOT gated on RSVP the way the door codes are.
drop policy if exists photos_select on public.photos;
create policy photos_select on public.photos
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists photos_insert on public.photos;
create policy photos_insert on public.photos
  for insert to authenticated
  with check ( (select public.is_member()) and uploaded_by = (select auth.uid()) );

drop policy if exists photos_update on public.photos;
create policy photos_update on public.photos
  for update to authenticated
  using      ( uploaded_by = (select auth.uid()) or (select public.is_organizer()) )
  with check ( uploaded_by = (select auth.uid()) or (select public.is_organizer()) );

drop policy if exists photos_delete on public.photos;
create policy photos_delete on public.photos
  for delete to authenticated
  using ( uploaded_by = (select auth.uid()) or (select public.is_organizer()) );

-- ---------------------------------------------------------------------------
-- Storage object policies. Paths look like:
--   trips/{trip_id}/houses/{house_id}/{uuid}.webp
-- ---------------------------------------------------------------------------
drop policy if exists "photos read"   on storage.objects;
drop policy if exists "photos insert" on storage.objects;
drop policy if exists "photos update" on storage.objects;
drop policy if exists "photos delete" on storage.objects;

create policy "photos read" on storage.objects
  for select to authenticated
  using ( bucket_id = 'photos' and (select public.is_member()) );

create policy "photos insert" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'photos'
    and (select public.is_member())
    and (storage.foldername(name))[1] = 'trips'
    and owner_id = (select auth.uid())::text
  );

create policy "photos update" on storage.objects
  for update to authenticated
  using      ( bucket_id = 'photos'
               and (owner_id = (select auth.uid())::text or (select public.is_organizer())) )
  with check ( bucket_id = 'photos'
               and (owner_id = (select auth.uid())::text or (select public.is_organizer())) );

create policy "photos delete" on storage.objects
  for delete to authenticated
  using ( bucket_id = 'photos'
          and (owner_id = (select auth.uid())::text or (select public.is_organizer())) );

-- ======================== 16_agenda.sql ========================

-- ===========================================================================
-- 16_agenda.sql — the dinner rotation and the event calendar.
--
-- Dinners are claimed by HOUSEHOLD, not by person: cooking a beach-house
-- dinner is a family effort, and the rotation people actually care about is
-- "whose night is it".
--
-- Both tables are fully collaborative. Anyone can fix the schedule — that is
-- the point of a shared agenda, and an audit trail is overkill for a family.
-- ===========================================================================

create table if not exists public.meals (
  id           uuid primary key default gen_random_uuid(),
  trip_id      uuid not null references public.trips(id) on delete cascade,
  meal_date    date not null,
  meal_type    public.meal_type not null default 'dinner',
  household_id uuid references public.households(id) on delete set null,
  title        text not null default '',
  description  text,
  created_by   uuid not null references public.profiles(id) on delete restrict,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  -- One dinner per night. Re-assigning edits the row instead of stacking
  -- duplicates nobody can tell apart.
  unique (trip_id, meal_date, meal_type)
);

create index if not exists meals_trip_date_idx on public.meals (trip_id, meal_date);

-- Optional named cooks within the household, for "Sue's doing the sides".
create table if not exists public.meal_cooks (
  meal_id    uuid not null references public.meals(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  note       text,
  primary key (meal_id, profile_id)
);

create table if not exists public.events (
  id          uuid primary key default gen_random_uuid(),
  trip_id     uuid not null references public.trips(id) on delete cascade,
  title       text not null check (length(btrim(title)) between 1 and 140),
  description text,
  kind        public.event_kind not null default 'activity',
  all_day     boolean not null default false,
  event_date  date not null,
  start_time  time,
  end_time    time,
  location    text,
  url         text check (url is null or url ~* '^https?://'),
  created_by  uuid not null references public.profiles(id) on delete restrict,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint events_times_ordered check (end_time is null or start_time is null or end_time >= start_time)
);

create index if not exists events_trip_date_idx on public.events (trip_id, event_date, start_time);

grant select, insert, update, delete on public.meals      to authenticated;
grant select, insert, update, delete on public.meal_cooks to authenticated;
grant select, insert, update, delete on public.events     to authenticated;

drop trigger if exists meals_touch on public.meals;
create trigger meals_touch before update on public.meals
  for each row execute function public.touch_updated_at();
drop trigger if exists events_touch on public.events;
create trigger events_touch before update on public.events
  for each row execute function public.touch_updated_at();

alter table public.meals      enable row level security;
alter table public.meal_cooks enable row level security;
alter table public.events     enable row level security;

do $$
declare t text;
begin
  foreach t in array array['meals','events'] loop
    execute format('drop policy if exists %1$s_select on public.%1$I', t);
    execute format('drop policy if exists %1$s_insert on public.%1$I', t);
    execute format('drop policy if exists %1$s_modify on public.%1$I', t);
    execute format('drop policy if exists %1$s_remove on public.%1$I', t);

    execute format($f$create policy %1$s_select on public.%1$I
      for select to authenticated using ( (select public.is_member()) )$f$, t);
    execute format($f$create policy %1$s_insert on public.%1$I
      for insert to authenticated
      with check ( (select public.is_member()) and created_by = (select auth.uid()) )$f$, t);
    execute format($f$create policy %1$s_modify on public.%1$I
      for update to authenticated
      using ( (select public.is_member()) ) with check ( (select public.is_member()) )$f$, t);
    execute format($f$create policy %1$s_remove on public.%1$I
      for delete to authenticated using ( (select public.is_member()) )$f$, t);
  end loop;
end $$;

drop policy if exists meal_cooks_all on public.meal_cooks;
create policy meal_cooks_all on public.meal_cooks
  for all to authenticated
  using ( (select public.is_member()) ) with check ( (select public.is_member()) );

-- ======================== 17_rsvp_upsert.sql ========================

-- ===========================================================================
-- 17_rsvp_upsert.sql — let an RSVP be saved without a read-then-write race.
--
-- The client decided insert-vs-update from whatever the query cache held, so
-- changing your answer before the refetch landed tried a second INSERT and hit
--   duplicate key value violates unique constraint "rsvps_one_per_member"
--
-- An upsert removes the race, but ON CONFLICT cannot target a PARTIAL unique
-- index without repeating its predicate, which PostgREST has no way to send.
-- A plain unique constraint behaves identically here: Postgres treats NULLs as
-- distinct by default, so guest rows (profile_id IS NULL) still never collide
-- with each other.
-- ===========================================================================

drop index if exists public.rsvps_one_per_member;

alter table public.rsvps
  drop constraint if exists rsvps_one_per_member;

alter table public.rsvps
  add constraint rsvps_one_per_member unique (trip_id, profile_id);

-- ======================== 18_money.sql ========================

-- ===========================================================================
-- 18_money.sql — expenses, splits and settling up.
--
-- Money is INTEGER CENTS everywhere. Floats drift, and a split that is a
-- hundredth of a cent off is a split that will not reconcile.
--
-- There is no server, so nothing stops a hand-written REST call from writing
-- splits that do not add up. The deferred constraint triggers below are what
-- actually make that impossible, and save_expense() is the only transaction
-- boundary the browser can get.
-- ===========================================================================

create table if not exists public.expenses (
  id           uuid primary key default gen_random_uuid(),
  trip_id      uuid not null references public.trips(id) on delete cascade,
  payer_id     uuid not null references public.profiles(id) on delete restrict,
  amount_cents integer not null check (amount_cents > 0 and amount_cents <= 100000000),
  category     public.expense_category not null default 'other',
  description  text not null default '' check (length(description) <= 300),
  incurred_on  date not null default (now() at time zone 'America/Chicago')::date,
  split_method public.split_method not null default 'equal',
  receipt_path text,
  created_by   uuid not null references public.profiles(id) on delete restrict,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index if not exists expenses_trip_idx  on public.expenses (trip_id, incurred_on desc);
create index if not exists expenses_payer_idx on public.expenses (payer_id);

-- One row per person the cost lands on. This is what "select which users to
-- split with" means: explicit, per-person, with the amount stored rather than
-- recomputed.
create table if not exists public.expense_splits (
  expense_id  uuid not null references public.expenses(id) on delete cascade,
  profile_id  uuid not null references public.profiles(id) on delete restrict,
  share_cents integer not null check (share_cents >= 0),
  weight      numeric(6,3) not null default 1,
  primary key (expense_id, profile_id)
);

create index if not exists expense_splits_profile_idx on public.expense_splits (profile_id);

-- Cash that actually changed hands, so balances can be zeroed out.
create table if not exists public.settlements (
  id              uuid primary key default gen_random_uuid(),
  trip_id         uuid not null references public.trips(id) on delete cascade,
  from_profile_id uuid not null references public.profiles(id) on delete restrict,
  to_profile_id   uuid not null references public.profiles(id) on delete restrict,
  amount_cents    integer not null check (amount_cents > 0),
  settled_on      date not null default (now() at time zone 'America/Chicago')::date,
  method          text,
  note            text,
  created_by      uuid not null references public.profiles(id) on delete restrict,
  created_at      timestamptz not null default now(),
  constraint settlement_distinct_parties check (from_profile_id <> to_profile_id)
);

create index if not exists settlements_trip_idx on public.settlements (trip_id);

grant select, insert, update, delete on public.expenses       to authenticated;
grant select, insert, update, delete on public.expense_splits to authenticated;
grant select, insert, update, delete on public.settlements    to authenticated;

drop trigger if exists expenses_touch on public.expenses;
create trigger expenses_touch before update on public.expenses
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- The invariant: an expense's splits always sum to its amount.
--
-- DEFERRABLE INITIALLY DEFERRED so the check runs at COMMIT — otherwise
-- rewriting a split set would trip halfway through, when the rows are
-- momentarily inconsistent by design.
-- ---------------------------------------------------------------------------
create or replace function public.assert_split_total()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_expense uuid := coalesce(new.expense_id, old.expense_id);
  v_amount  integer;
  v_sum     integer;
begin
  select amount_cents into v_amount from public.expenses where id = v_expense;
  if v_amount is null then return null; end if;  -- parent deleted; cascade in flight

  select coalesce(sum(share_cents), 0) into v_sum
    from public.expense_splits where expense_id = v_expense;

  if v_sum <> v_amount then
    raise exception 'Splits add up to %c but the expense is %c', v_sum, v_amount
      using errcode = 'check_violation';
  end if;
  return null;
end;
$$;

drop trigger if exists expense_splits_total_check on public.expense_splits;
create constraint trigger expense_splits_total_check
  after insert or update or delete on public.expense_splits
  deferrable initially deferred
  for each row execute function public.assert_split_total();

create or replace function public.assert_expense_total()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare v_sum integer;
begin
  select coalesce(sum(share_cents), 0) into v_sum
    from public.expense_splits where expense_id = new.id;
  if v_sum <> new.amount_cents then
    raise exception 'The amount was changed to %c but the splits add up to %c',
      new.amount_cents, v_sum using errcode = 'check_violation';
  end if;
  return null;
end;
$$;

drop trigger if exists expenses_total_check on public.expenses;
create constraint trigger expenses_total_check
  after insert or update of amount_cents on public.expenses
  deferrable initially deferred
  for each row execute function public.assert_expense_total();

-- ---------------------------------------------------------------------------
-- RLS. Collaborative for logistics, payer-owned for money: nobody edits the
-- receipt you paid for.
-- ---------------------------------------------------------------------------
alter table public.expenses       enable row level security;
alter table public.expense_splits enable row level security;
alter table public.settlements    enable row level security;

drop policy if exists expenses_select on public.expenses;
create policy expenses_select on public.expenses
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists expenses_insert on public.expenses;
create policy expenses_insert on public.expenses
  for insert to authenticated
  with check ( (select public.is_member()) and created_by = (select auth.uid()) );

drop policy if exists expenses_update on public.expenses;
create policy expenses_update on public.expenses
  for update to authenticated
  using      ( payer_id = (select auth.uid()) or created_by = (select auth.uid())
               or (select public.is_organizer()) )
  with check ( payer_id = (select auth.uid()) or created_by = (select auth.uid())
               or (select public.is_organizer()) );

drop policy if exists expenses_delete on public.expenses;
create policy expenses_delete on public.expenses
  for delete to authenticated
  using ( payer_id = (select auth.uid()) or created_by = (select auth.uid())
          or (select public.is_organizer()) );

drop policy if exists splits_select on public.expense_splits;
create policy splits_select on public.expense_splits
  for select to authenticated using ( (select public.is_member()) );

-- Splits inherit the parent expense's permissions.
drop policy if exists splits_write on public.expense_splits;
create policy splits_write on public.expense_splits
  for all to authenticated
  using ( exists (select 1 from public.expenses e
                   where e.id = expense_splits.expense_id
                     and ( e.payer_id = (select auth.uid())
                           or e.created_by = (select auth.uid())
                           or (select public.is_organizer()) )) )
  with check ( exists (select 1 from public.expenses e
                        where e.id = expense_splits.expense_id
                          and ( e.payer_id = (select auth.uid())
                                or e.created_by = (select auth.uid())
                                or (select public.is_organizer()) )) );

drop policy if exists settlements_select on public.settlements;
create policy settlements_select on public.settlements
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists settlements_insert on public.settlements;
create policy settlements_insert on public.settlements
  for insert to authenticated
  with check ( (select public.is_member()) and created_by = (select auth.uid())
               and ( from_profile_id = (select auth.uid())
                     or to_profile_id = (select auth.uid())
                     or (select public.is_organizer()) ) );

drop policy if exists settlements_delete on public.settlements;
create policy settlements_delete on public.settlements
  for delete to authenticated
  using ( from_profile_id = (select auth.uid()) or to_profile_id = (select auth.uid())
          or (select public.is_organizer()) );

-- ======================== 19_balances.sql ========================

-- ===========================================================================
-- 19_balances.sql — saving an expense atomically, and who owes whom.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- An expense and its splits must land together or not at all. The browser has
-- no transaction, so a crash between the two writes would leave an expense
-- whose splits do not add up — which the deferred trigger would then reject on
-- every later edit. This function is the transaction.
--
-- SECURITY INVOKER on purpose: RLS still applies to every statement inside, so
-- this grants no privilege the caller did not already have.
-- ---------------------------------------------------------------------------
create or replace function public.save_expense(
  p_expense jsonb,
  p_splits  jsonb
) returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id  uuid;
  v_sum integer;
  v_amt integer := (p_expense->>'amount_cents')::integer;
begin
  if p_splits is null or jsonb_array_length(p_splits) = 0 then
    raise exception 'Choose at least one person to split this with'
      using errcode = 'check_violation';
  end if;

  select coalesce(sum((s->>'share_cents')::integer), 0) into v_sum
    from jsonb_array_elements(p_splits) s;

  -- Say this plainly here; the deferred trigger's message is for developers.
  if v_sum <> v_amt then
    raise exception 'The shares add up to $%, but the expense is $%',
      to_char(v_sum / 100.0, 'FM999999990.00'), to_char(v_amt / 100.0, 'FM999999990.00')
      using errcode = 'check_violation';
  end if;

  insert into public.expenses as e
    (id, trip_id, payer_id, amount_cents, category, description,
     incurred_on, split_method, receipt_path, created_by)
  select
    coalesce((p_expense->>'id')::uuid, gen_random_uuid()),
    (p_expense->>'trip_id')::uuid,
    (p_expense->>'payer_id')::uuid,
    v_amt,
    coalesce((p_expense->>'category')::public.expense_category, 'other'),
    coalesce(p_expense->>'description', ''),
    coalesce((p_expense->>'incurred_on')::date, current_date),
    coalesce((p_expense->>'split_method')::public.split_method, 'equal'),
    nullif(p_expense->>'receipt_path', ''),
    auth.uid()
  on conflict (id) do update set
    payer_id     = excluded.payer_id,
    amount_cents = excluded.amount_cents,
    category     = excluded.category,
    description  = excluded.description,
    incurred_on  = excluded.incurred_on,
    split_method = excluded.split_method,
    receipt_path = excluded.receipt_path
  returning e.id into v_id;

  -- RLS filtered the row out rather than erroring: the caller may not edit it.
  if v_id is null then
    raise exception 'You can only edit an expense you paid for or entered'
      using errcode = '42501';
  end if;

  delete from public.expense_splits where expense_id = v_id;

  insert into public.expense_splits (expense_id, profile_id, share_cents, weight)
  select v_id,
         (s->>'profile_id')::uuid,
         (s->>'share_cents')::integer,
         coalesce((s->>'weight')::numeric, 1)
  from jsonb_array_elements(p_splits) s;

  return v_id;  -- deferred checks fire here, at COMMIT
end;
$$;

revoke execute on function public.save_expense(jsonb, jsonb) from public, anon;
grant   execute on function public.save_expense(jsonb, jsonb) to authenticated;

-- ---------------------------------------------------------------------------
-- Balances.
--
-- security_invoker = true is NOT optional. A view runs as its OWNER by
-- default, and the owner bypasses RLS — a plain view over expenses would be a
-- data leak wearing a disguise.
-- ---------------------------------------------------------------------------
drop view if exists public.trip_balances;
create view public.trip_balances
with (security_invoker = true) as
with paid as (
  select trip_id, payer_id as profile_id, sum(amount_cents)::bigint as cents
    from public.expenses group by 1, 2
),
owed as (
  select e.trip_id, s.profile_id, sum(s.share_cents)::bigint as cents
    from public.expense_splits s
    join public.expenses e on e.id = s.expense_id
   group by 1, 2
),
sent as (
  select trip_id, from_profile_id as profile_id, sum(amount_cents)::bigint as cents
    from public.settlements group by 1, 2
),
received as (
  select trip_id, to_profile_id as profile_id, sum(amount_cents)::bigint as cents
    from public.settlements group by 1, 2
),
keys as (
  select trip_id, profile_id from paid
  union select trip_id, profile_id from owed
  union select trip_id, profile_id from sent
  union select trip_id, profile_id from received
)
select
  k.trip_id,
  k.profile_id,
  coalesce(p.cents, 0) as paid_cents,
  coalesce(o.cents, 0) as owed_cents,
  -- Positive: the group owes them. Negative: they owe the group.
  -- Handing over cash settles your debt, so it counts like paying.
  ( coalesce(p.cents,0) - coalesce(o.cents,0)
    + coalesce(s.cents,0) - coalesce(r.cents,0) )::bigint as net_cents
from keys k
left join paid     p using (trip_id, profile_id)
left join owed     o using (trip_id, profile_id)
left join sent     s using (trip_id, profile_id)
left join received r using (trip_id, profile_id);

revoke all on public.trip_balances from public, anon;
grant select on public.trip_balances to authenticated;

-- ======================== 20_journal.sql ========================

-- ===========================================================================
-- 20_journal.sql — the group journal.
--
-- Author-owned, unlike the meals and calendar. Anyone can fix the dinner
-- schedule because that is shared logistics; nobody rewrites what you wrote.
-- ===========================================================================

create table if not exists public.journal_entries (
  id         uuid primary key default gen_random_uuid(),
  trip_id    uuid not null references public.trips(id) on delete cascade,
  author_id  uuid not null references public.profiles(id) on delete restrict,
  title      text not null default '',
  body       text not null default '' check (length(body) <= 50000),
  entry_date date not null default (now() at time zone 'America/Chicago')::date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint journal_has_content
    check (nullif(btrim(title), '') is not null or nullif(btrim(body), '') is not null)
);

create index if not exists journal_trip_date_idx
  on public.journal_entries (trip_id, entry_date desc, created_at desc);

grant select, insert, update, delete on public.journal_entries to authenticated;

drop trigger if exists journal_touch on public.journal_entries;
create trigger journal_touch before update on public.journal_entries
  for each row execute function public.touch_updated_at();

alter table public.journal_entries enable row level security;

drop policy if exists journal_select on public.journal_entries;
create policy journal_select on public.journal_entries
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists journal_insert on public.journal_entries;
create policy journal_insert on public.journal_entries
  for insert to authenticated
  with check ( (select public.is_member()) and author_id = (select auth.uid()) );

-- The with-check stops authorship being handed to someone else on update.
drop policy if exists journal_update on public.journal_entries;
create policy journal_update on public.journal_entries
  for update to authenticated
  using      ( author_id = (select auth.uid()) )
  with check ( author_id = (select auth.uid()) );

drop policy if exists journal_delete on public.journal_entries;
create policy journal_delete on public.journal_entries
  for delete to authenticated
  using ( author_id = (select auth.uid()) or (select public.is_organizer()) );

-- ======================== 21_avatars.sql ========================

-- ===========================================================================
-- 21_avatars.sql — profile pictures.
--
-- Same bucket as photos, under avatars/{user_id}/. The existing insert policy
-- only allows the trips/ prefix, so avatars need their own rule: you may write
-- inside your own folder and nobody else's.
-- ===========================================================================

drop policy if exists "avatars insert" on storage.objects;
create policy "avatars insert" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'photos'
    and (select public.is_member())
    and (storage.foldername(name))[1] = 'avatars'
    and (storage.foldername(name))[2] = (select auth.uid())::text
    and owner_id = (select auth.uid())::text
  );

drop policy if exists "avatars modify" on storage.objects;
create policy "avatars modify" on storage.objects
  for update to authenticated
  using (
    bucket_id = 'photos'
    and (storage.foldername(name))[1] = 'avatars'
    and (storage.foldername(name))[2] = (select auth.uid())::text
  )
  with check (
    bucket_id = 'photos'
    and (storage.foldername(name))[1] = 'avatars'
    and (storage.foldername(name))[2] = (select auth.uid())::text
  );

drop policy if exists "avatars remove" on storage.objects;
create policy "avatars remove" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'photos'
    and (storage.foldername(name))[1] = 'avatars'
    and (storage.foldername(name))[2] = (select auth.uid())::text
  );

-- ======================== 22_event_comments.sql ========================

-- ===========================================================================
-- 22_event_comments.sql — a thread under each calendar event.
--
-- Deliberately a table per thing rather than one polymorphic comments table:
-- a generic (target_type, target_id) pair cannot carry a foreign key, so
-- deleting an event would silently orphan its comments. If photos or meals
-- want comments later, they get their own table and their own cascade.
-- ===========================================================================

create table if not exists public.event_comments (
  id         uuid primary key default gen_random_uuid(),
  event_id   uuid not null references public.events(id) on delete cascade,
  author_id  uuid not null references public.profiles(id) on delete restrict,
  body       text not null check (length(btrim(body)) between 1 and 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists event_comments_event_idx
  on public.event_comments (event_id, created_at);

grant select, insert, update, delete on public.event_comments to authenticated;

drop trigger if exists event_comments_touch on public.event_comments;
create trigger event_comments_touch before update on public.event_comments
  for each row execute function public.touch_updated_at();

alter table public.event_comments enable row level security;

drop policy if exists event_comments_select on public.event_comments;
create policy event_comments_select on public.event_comments
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists event_comments_insert on public.event_comments;
create policy event_comments_insert on public.event_comments
  for insert to authenticated
  with check ( (select public.is_member()) and author_id = (select auth.uid()) );

-- Author-owned, like the journal: the events themselves are collaborative, but
-- nobody rewrites what you said about one. The with-check also stops
-- authorship being reassigned on update.
drop policy if exists event_comments_update on public.event_comments;
create policy event_comments_update on public.event_comments
  for update to authenticated
  using      ( author_id = (select auth.uid()) )
  with check ( author_id = (select auth.uid()) );

drop policy if exists event_comments_delete on public.event_comments;
create policy event_comments_delete on public.event_comments
  for delete to authenticated
  using ( author_id = (select auth.uid()) or (select public.is_organizer()) );

-- ======================== 23_events_organizer_only.sql ========================

-- ===========================================================================
-- 23_events_organizer_only.sql — organizers own the calendar.
--
-- Events were fully collaborative, alongside the dinner rotation. The calendar
-- turns out to be different: a booked charter or a reservation is not a thing
-- anyone should be able to move or delete.
--
-- Comments stay open to every member. Being able to ask "what time?" under an
-- event is the point of them, and a comment cannot change the plan.
-- Dinners stay collaborative too — that rotation is genuinely shared.
-- ===========================================================================

drop policy if exists events_select on public.events;
drop policy if exists events_insert on public.events;
drop policy if exists events_modify on public.events;
drop policy if exists events_remove on public.events;

create policy events_select on public.events
  for select to authenticated
  using ( (select public.is_member()) );

create policy events_insert on public.events
  for insert to authenticated
  with check ( (select public.is_organizer()) and created_by = (select auth.uid()) );

create policy events_modify on public.events
  for update to authenticated
  using      ( (select public.is_organizer()) )
  with check ( (select public.is_organizer()) );

create policy events_remove on public.events
  for delete to authenticated
  using ( (select public.is_organizer()) );

-- ======================== 24_rsvp_self_only.sql ========================

-- ===========================================================================
-- 24_rsvp_self_only.sql — you RSVP for yourself, and only yourself.
--
-- The policies previously allowed two extra paths that no screen ever used:
-- a row with a guest_name and no profile_id, and an organizer answering on
-- anyone's behalf. Neither is wanted: an RSVP is a statement about yourself,
-- so nobody else gets to make it or change it — organizers included.
--
-- DELETE keeps an organizer path. That is cleanup, not answering for someone:
-- when a person leaves the family their row would otherwise sit on the roster
-- permanently with nobody able to remove it.
-- ===========================================================================

drop policy if exists rsvps_insert on public.rsvps;
create policy rsvps_insert on public.rsvps
  for insert to authenticated
  with check (
    (select public.is_member())
    and profile_id = (select auth.uid())
    and created_by = (select auth.uid())
  );

drop policy if exists rsvps_update on public.rsvps;
create policy rsvps_update on public.rsvps
  for update to authenticated
  using      ( profile_id = (select auth.uid()) )
  -- Without the same test in the check, you could hand your row to someone
  -- else by editing profile_id and answer for them that way.
  with check ( profile_id = (select auth.uid()) );

drop policy if exists rsvps_delete on public.rsvps;
create policy rsvps_delete on public.rsvps
  for delete to authenticated
  using ( profile_id = (select auth.uid()) or (select public.is_organizer()) );

-- ======================== 25_expense_check_rereads.sql ========================

-- ===========================================================================
-- 25_expense_check_rereads.sql — make the deferred amount check read current
-- state instead of the row it was queued with.
--
-- assert_expense_total compared `new.amount_cents` against the splits. A
-- deferred trigger captures `new` when it is QUEUED but runs its body at
-- COMMIT, so editing an expense twice inside one transaction compared the
-- first amount against the final splits and failed on a perfectly valid edit.
--
-- Each REST call is its own transaction today, so this did not fire in the
-- app — but it is a false failure waiting for anything that batches, and a
-- check that reads stale state is not really checking the invariant.
-- Re-reading the row makes it hold whatever order the writes arrive in.
-- ===========================================================================

create or replace function public.assert_expense_total()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_amount integer;
  v_sum    integer;
begin
  -- Read the row as it stands now, not as it was when this was queued.
  select amount_cents into v_amount from public.expenses where id = new.id;
  if v_amount is null then return null; end if;  -- deleted since; cascade handles it

  select coalesce(sum(share_cents), 0) into v_sum
    from public.expense_splits where expense_id = new.id;

  if v_sum <> v_amount then
    raise exception 'The expense is %c but the shares add up to %c', v_amount, v_sum
      using errcode = 'check_violation';
  end if;
  return null;
end;
$$;

-- ======================== 26_meals_claim.sql ========================

-- ===========================================================================
-- 26_meals_claim.sql — you claim a night for your own household.
--
-- Meals were fully collaborative, so anyone could put any family on any night
-- and just as easily take a night off them. Claiming only means something if
-- nobody else can do it for you.
--
--   unclaimed night  -> anyone may take it (for their own household)
--   your night       -> you may edit the menu or give it back
--   someone else's   -> hands off, unless you are an organizer
--
-- Both clauses are needed and do different jobs: `using` decides which rows
-- you may touch at all, `with check` decides what they are allowed to look
-- like afterwards. Without the check you could claim an unclaimed night on
-- behalf of a household that is not yours.
-- ===========================================================================

drop policy if exists meals_insert on public.meals;
create policy meals_insert on public.meals
  for insert to authenticated
  with check (
    (select public.is_member())
    and created_by = (select auth.uid())
    and (
      (select public.is_organizer())
      or household_id is null
      or household_id = (select public.my_household_id())
    )
  );

drop policy if exists meals_modify on public.meals;
create policy meals_modify on public.meals
  for update to authenticated
  using (
    (select public.is_member())
    and (
      (select public.is_organizer())
      or household_id is null
      or household_id = (select public.my_household_id())
    )
  )
  with check (
    (select public.is_member())
    and (
      (select public.is_organizer())
      or household_id is null
      or household_id = (select public.my_household_id())
    )
  );

drop policy if exists meals_remove on public.meals;
create policy meals_remove on public.meals
  for delete to authenticated
  using (
    (select public.is_member())
    and (
      (select public.is_organizer())
      or household_id is null
      or household_id = (select public.my_household_id())
    )
  );

-- ======================== 27_meals_eat_out.sql ========================

-- ===========================================================================
-- 27_meals_eat_out.sql — a night where nobody cooks.
--
-- "Nobody has claimed it yet" and "we're going out" looked identical before:
-- both were simply an unclaimed night, so an undecided night and a settled one
-- were indistinguishable.
--
-- The constraint states the thing that has to stay true: a night is either
-- somebody's to cook or a night out, never both. The existing claim policies
-- cover this for free — a night out has no household, so it stays editable by
-- anyone, exactly like an unclaimed one.
-- ===========================================================================

alter table public.meals
  add column if not exists eat_out boolean not null default false;

alter table public.meals
  drop constraint if exists meals_not_both_cook_and_out;

alter table public.meals
  add constraint meals_not_both_cook_and_out
  check (not (eat_out and household_id is not null));

-- ======================== 28_photo_thumbs.sql ========================

-- ===========================================================================
-- 28_photo_thumbs.sql — a small copy for the grid.
--
-- The gallery downloaded full-size images to draw them as squares a couple of
-- hundred pixels wide, so opening the page pulled megabytes to show thumbnails.
-- Uploads now store a second, small file and the grid uses that; the lightbox
-- still loads the full one.
--
-- Nullable on purpose: photos uploaded before this have no thumbnail and the
-- grid falls back to the full image rather than showing nothing.
-- ===========================================================================

alter table public.photos
  add column if not exists thumb_path text;

-- ======================== 29_admin_edit_profiles.sql ========================

-- ===========================================================================
-- 29_admin_edit_profiles.sql — organizers can fix someone else's name and
-- household.
--
-- People set their own name and household, and nobody could correct them. In
-- practice a couple of family members never finish setting up, so the roster
-- shows an email prefix and the dinner rotation has nobody to claim a night.
--
-- This needs a function for the same reason role changes did: the column-level
-- grants let you update only your OWN row, and the profiles policy enforces
-- it. Those grants are what stop a member rewriting anyone they like, so
-- neither is relaxed — a definer function is the narrow exception.
-- ===========================================================================

-- The screen needs the raw name to edit and the id to pick a household.
-- CREATE OR REPLACE cannot insert a column mid-list, only append, so this
-- drops first. Nothing depends on the view but the Members screen.
drop view if exists public.admin_members;
create view public.admin_members
with (security_invoker = true) as
select
  a.email,
  a.note,
  a.role                       as invited_role,
  a.created_at                 as invited_at,
  p.id                         as profile_id,
  p.full_name,
  p.display_name,
  p.role                       as profile_role,
  coalesce(p.is_active, false) as is_active,
  p.household_id,
  h.name                       as household_name,
  (p.id is not null)           as has_signed_in
from public.allowed_emails a
left join public.profiles   p on p.email = a.email
left join public.households h on h.id = p.household_id;

revoke all on public.admin_members from public, anon;
grant select on public.admin_members to authenticated;

create or replace function public.admin_update_profile(
  target_id      uuid,
  new_full_name  text,
  new_household  uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not (select public.is_organizer()) then
    raise exception 'Organizers only.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.profiles where id = target_id) then
    raise exception 'No such member.' using errcode = 'no_data_found';
  end if;

  -- Deliberately does not touch role or is_active. Promotion goes through
  -- admin_set_role, which protects the last organizer; membership is derived
  -- from the invite list. Letting this write either would route around both.
  update public.profiles
     set full_name    = coalesce(btrim(new_full_name), ''),
         household_id = new_household
   where id = target_id;
end;
$$;

revoke execute on function public.admin_update_profile(uuid, text, uuid) from public, anon;
grant   execute on function public.admin_update_profile(uuid, text, uuid) to authenticated;

-- ======================== 30_owner_role.sql ========================

-- ===========================================================================
-- 30_owner_role.sql — a tier above organizer.
--
-- Split from the migration that uses it on purpose: Postgres allows adding an
-- enum value inside a transaction but will not let the same transaction USE
-- it, and every migration runs in one. The value has to land and commit first.
-- ===========================================================================

alter type public.member_role add value if not exists 'owner';

-- ======================== 31_owner_powers.sql ========================

-- ===========================================================================
-- 31_owner_powers.sql — what the owner can do that an organizer cannot.
--
-- Organizers keep running the trip: trips, houses, the calendar, invites,
-- households. Managing PEOPLE moves up a tier — who holds which role, and
-- editing someone else's name or household.
--
-- The reason role changes must be owner-only is concrete: if an organizer
-- could set roles, they could make themselves owner, and the tier would mean
-- nothing.
-- ===========================================================================

create or replace function public.is_owner()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.profiles p
     where p.id = (select auth.uid())
       and p.is_active
       and p.role = 'owner'
  );
$$;

-- Owner outranks organizer, so every existing organizer check keeps passing
-- for the owner rather than each one needing to name both roles.
create or replace function public.is_organizer()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.profiles p
     where p.id = (select auth.uid())
       and p.is_active
       and p.role in ('organizer', 'owner')
  );
$$;

revoke execute on function public.is_owner() from public, anon;
grant   execute on function public.is_owner() to authenticated;

-- ---------------------------------------------------------------------------
-- Role changes: owner only, and the last owner cannot be demoted.
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_role(
  target_email text,
  new_role     public.member_role
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(target_email));
begin
  if not (select public.is_owner()) then
    raise exception 'Only the owner can change roles.' using errcode = '42501';
  end if;

  if new_role <> 'owner'
     and (select count(*) from public.allowed_emails where role = 'owner') <= 1
     and exists (select 1 from public.allowed_emails where email = v_email and role = 'owner') then
    raise exception 'That is the only owner. Make someone else the owner first.'
      using errcode = 'check_violation';
  end if;

  update public.allowed_emails set role = new_role where email = v_email;
  update public.profiles        set role = new_role where email = v_email;

  if not exists (select 1 from public.allowed_emails where email = v_email) then
    raise exception 'No such member.' using errcode = 'no_data_found';
  end if;
end;
$$;

revoke execute on function public.admin_set_role(text, public.member_role) from public, anon;
grant   execute on function public.admin_set_role(text, public.member_role) to authenticated;

-- ---------------------------------------------------------------------------
-- Editing someone else's details: owner only.
-- ---------------------------------------------------------------------------
create or replace function public.admin_update_profile(
  target_id      uuid,
  new_full_name  text,
  new_household  uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not (select public.is_owner()) then
    raise exception 'Only the owner can edit someone else''s details.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.profiles where id = target_id) then
    raise exception 'No such member.' using errcode = 'no_data_found';
  end if;

  update public.profiles
     set full_name    = coalesce(btrim(new_full_name), ''),
         household_id = new_household
   where id = target_id;
end;
$$;

revoke execute on function public.admin_update_profile(uuid, text, uuid) from public, anon;
grant   execute on function public.admin_update_profile(uuid, text, uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Removing an owner from the invite list would strip their access, which is a
-- way to unseat the owner without ever touching a role. Only an owner may.
-- ---------------------------------------------------------------------------
create or replace function public.protect_last_organizer()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if old.role = 'owner' and not (select public.is_owner()) then
    raise exception 'Only the owner can remove the owner.' using errcode = '42501';
  end if;

  if old.role in ('organizer', 'owner')
     and (select count(*) from public.allowed_emails where role in ('organizer', 'owner')) <= 1 then
    raise exception 'That is the only organizer. Make someone else an organizer first.'
      using errcode = 'check_violation';
  end if;
  return old;
end;
$$;

-- ======================== 32_households_owner.sql ========================

-- ===========================================================================
-- 32_households_owner.sql — households move up to the owner tier.
--
-- Any member could rename or create a household; only the Members screen being
-- organizer-gated kept that out of reach, and a UI gate is not a rule.
-- Households decide who cooks and how the house cost divides, so they belong
-- with the other people-shaped settings the owner holds.
--
-- Reading stays open to every member: the dinner rotation, the split picker
-- and the profile screen all need the list.
-- ===========================================================================

drop policy if exists households_select on public.households;
create policy households_select on public.households
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists households_insert on public.households;
create policy households_insert on public.households
  for insert to authenticated with check ( (select public.is_owner()) );

drop policy if exists households_update on public.households;
create policy households_update on public.households
  for update to authenticated
  using      ( (select public.is_owner()) )
  with check ( (select public.is_owner()) );

drop policy if exists households_delete on public.households;
create policy households_delete on public.households
  for delete to authenticated using ( (select public.is_owner()) );

-- ======================== 33_amenities.sql ========================

-- ===========================================================================
-- 33_amenities.sql — what each house actually has.
--
-- A shared vocabulary rather than free text per house. The whole point is
-- comparing years — "which houses had a private pool?" — and free text
-- fragments into "Grill", "grill" and "BBQ", which answers nothing.
-- ===========================================================================

create table if not exists public.amenities (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (length(btrim(name)) between 2 and 40),
  sort_order smallint not null default 0,
  created_at timestamptz not null default now()
);

-- Uniqueness on the lowered name, not the name. A plain unique constraint
-- would accept "Grill" and "grill" as two amenities and quietly defeat the
-- reason for having a shared list at all.
create unique index if not exists amenities_name_unique on public.amenities (lower(btrim(name)));

create table if not exists public.house_amenities (
  house_id   uuid not null references public.houses(id) on delete cascade,
  amenity_id uuid not null references public.amenities(id) on delete cascade,
  added_by   uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (house_id, amenity_id)
);

create index if not exists house_amenities_amenity_idx on public.house_amenities (amenity_id);

grant select, insert, update, delete on public.amenities       to authenticated;
grant select, insert, update, delete on public.house_amenities to authenticated;

alter table public.amenities       enable row level security;
alter table public.house_amenities enable row level security;

-- ---------------------------------------------------------------------------
-- Anyone may add an amenity: low risk, and it saves a text to an organizer.
-- Renaming or deleting one reaches across every house in every year — a delete
-- cascades the tick off all of them — so that sits with the owner.
-- ---------------------------------------------------------------------------
drop policy if exists amenities_select on public.amenities;
create policy amenities_select on public.amenities
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists amenities_insert on public.amenities;
create policy amenities_insert on public.amenities
  for insert to authenticated with check ( (select public.is_member()) );

drop policy if exists amenities_update on public.amenities;
create policy amenities_update on public.amenities
  for update to authenticated
  using ( (select public.is_owner()) ) with check ( (select public.is_owner()) );

drop policy if exists amenities_delete on public.amenities;
create policy amenities_delete on public.amenities
  for delete to authenticated using ( (select public.is_owner()) );

-- Ticking is open to every member, like the gate-code panel: whoever notices
-- the grill on the deck records it.
drop policy if exists house_amenities_select on public.house_amenities;
create policy house_amenities_select on public.house_amenities
  for select to authenticated using ( (select public.is_member()) );

drop policy if exists house_amenities_insert on public.house_amenities;
create policy house_amenities_insert on public.house_amenities
  for insert to authenticated with check ( (select public.is_member()) );

drop policy if exists house_amenities_delete on public.house_amenities;
create policy house_amenities_delete on public.house_amenities
  for delete to authenticated using ( (select public.is_member()) );

-- ---------------------------------------------------------------------------
-- A starting vocabulary. on conflict so re-running changes nothing.
-- ---------------------------------------------------------------------------
insert into public.amenities (name, sort_order) values
  ('Private pool', 10),
  ('Community pool', 20),
  ('Hot tub', 30),
  ('Grill', 40),
  ('Golf cart', 50),
  ('Boat dock', 60),
  ('Beach access', 70),
  ('Washer & dryer', 80),
  ('Elevator', 90),
  ('Covered parking', 100),
  ('Outdoor shower', 110),
  ('Fire pit', 120),
  ('Pet friendly', 130),
  ('Kayaks', 140)
on conflict do nothing;

-- ======================== 34_owner_guest_rsvps.sql ========================

-- ===========================================================================
-- 34_owner_guest_rsvps.sql — the owner can add people who will never log in.
--
-- Migration 24 closed RSVPs to "yourself only", which also removed guest rows
-- and left family without accounts off the roster entirely. This restores
-- guests for the OWNER alone, and deliberately not the ability to answer for
-- a member: an RSVP about a person who can speak for themselves stays theirs.
--
-- The shape of a guest row is what enforces that split — profile_id IS NULL
-- with a name — so the policies can allow one without allowing the other.
-- ===========================================================================

drop policy if exists rsvps_insert on public.rsvps;
create policy rsvps_insert on public.rsvps
  for insert to authenticated
  with check (
    (select public.is_member())
    and created_by = (select auth.uid())
    and (
      profile_id = (select auth.uid())                         -- your own answer
      or (profile_id is null and (select public.is_owner()))   -- a guest you are adding
    )
  );

drop policy if exists rsvps_update on public.rsvps;
create policy rsvps_update on public.rsvps
  for update to authenticated
  using (
    profile_id = (select auth.uid())
    or (profile_id is null and (select public.is_owner()))
  )
  -- Repeating the test in the check is what stops a row changing sides: a
  -- member cannot turn their answer into a guest row, and the owner cannot
  -- turn a guest row into somebody's answer.
  with check (
    profile_id = (select auth.uid())
    or (profile_id is null and (select public.is_owner()))
  );

drop policy if exists rsvps_delete on public.rsvps;
create policy rsvps_delete on public.rsvps
  for delete to authenticated
  using ( profile_id = (select auth.uid()) or (select public.is_organizer()) );

-- ======================== 35_owner_rsvps_members.sql ========================

-- ===========================================================================
-- 35_owner_rsvps_members.sql — the owner can answer for a member too.
--
-- Guests alone were not enough: nothing stopped typing the name of somebody
-- who already has an account, which put a phantom second copy of them on the
-- roster and double-counted them. Picking the real person fixes that, but it
-- means the owner setting an answer for someone who can speak for themselves.
--
-- The member always wins in the end — their own update policy is unchanged, so
-- they can correct whatever was entered for them. And created_by already
-- records who typed it, so the roster can say an answer was entered by someone
-- else rather than presenting it as the person's own words.
-- ===========================================================================

drop policy if exists rsvps_insert on public.rsvps;
create policy rsvps_insert on public.rsvps
  for insert to authenticated
  with check (
    (select public.is_member())
    and created_by = (select auth.uid())
    and (
      profile_id = (select auth.uid())   -- your own answer
      or (select public.is_owner())      -- the owner, for a member or a guest
    )
  );

drop policy if exists rsvps_update on public.rsvps;
create policy rsvps_update on public.rsvps
  for update to authenticated
  using      ( profile_id = (select auth.uid()) or (select public.is_owner()) )
  -- A member still cannot hand their row to anyone else: the first branch
  -- pins it to them, and they do not satisfy the second.
  with check ( profile_id = (select auth.uid()) or (select public.is_owner()) );

drop policy if exists rsvps_delete on public.rsvps;
create policy rsvps_delete on public.rsvps
  for delete to authenticated
  using ( profile_id = (select auth.uid()) or (select public.is_organizer()) );
